const stamp = s => Number.isNaN(new Date(s).getTime()) ? '—' : new Date(s).toLocaleString(language==='en'?'en-GB':'uk-UA', { day:'numeric', month:'short', hour:'2-digit', minute:'2-digit' });
let db, fatal = '', filter = 'all', wizard = { mode:'simple', system:'swiss' }, tieOrder = [], toastTimer, recoveryPending, trfPending;
function translateValue(value) { return translate(value,language); }
function localizeDOM() {
  for (const container of [root, modal]) {
    const walker = document.createTreeWalker(container, NodeFilter.SHOW_TEXT);
    const nodes=[]; let node; while (node=walker.nextNode()) nodes.push(node);
    nodes.forEach(n=>{ if (!n.parentElement.closest('script,style,[data-user-content]')) n.nodeValue=translateValue(n.nodeValue); });
    container.querySelectorAll('[aria-label],[placeholder],[title]').forEach(el=>['aria-label','placeholder','title'].forEach(a=>{if(el.hasAttribute(a))el.setAttribute(a,translateValue(el.getAttribute(a)))}));
  }
  document.documentElement.lang=language==='uk'?'uk':'en';
}
const stored = key => { try { return localStorage.getItem(key); } catch { return null; } };
const directoryKey = 'tournament-local-players';
const loadDirectory = () => clone(db.localPlayers || []);
const saveDirectory = value => { const next=clone(db); next.localPlayers=value; save(next); };
let language = stored('tournament-language') === 'en' ? 'en' : 'uk';
