  if(a==='match-menu'){
    dialog('Результат и неявка',`<p>Неявка начисляет очки, но не считается сыгранной партией и учитывается отдельно в коэффициентах.</p><div class="stack" style="margin-top:18px">${button('special-result','Белые победили без игры (+ −)','','data-id="'+esc(d.id)+'" data-result="+-"')}${button('special-result','Чёрные победили без игры (− +)','','data-id="'+esc(d.id)+'" data-result="-+"')}${button('special-result','Нічия без гри (F½ — F½)','','data-id="'+esc(d.id)+'" data-result="F½-F½"')}${button('special-result','Оба не явились (− −)','','data-id="'+esc(d.id)+'" data-result="--"')}${button('special-result','Сбросить результат','danger','data-id="'+esc(d.id)+'" data-result="clear"')}</div>`);return;
  }
  if(a==='special-result'){change(`Тур ${viewRound}: ${d.result==='clear'?'результат сброшен':'неявка '+d.result}`,t=>d.board!==undefined?setBoardResult(t,viewRound,d.id,Number(d.board),d.result==='clear'?null:d.result):setResult(t,viewRound,d.id,d.result==='clear'?null:d.result));modal.close();return}
  if(a==='close-round'){confirm('Завершить тур?',`Результаты тура ${viewRound} будут зафиксированы. При необходимости их можно исправить через «Вернуться к этому туру».`,'close-round-confirm');return}
  if(a==='close-round-confirm'){change(`Завершено тур ${t.rounds.length}`,closeRound);modal.close();if(current().status!=='finished'){try{change(`Створено тур ${current().rounds.length+1}`,addRound);navigate(`tour/${t.id}/rounds/${current().rounds.length}`);}catch(error){showToast(error.message,true);return}}else showToast('Турнір завершено. Підсумкові місця готові.');return}
