  if(a==='start-ask'){const count=isTeamSystem(t.system)?t.teams.length:t.players.length,rounds=t.system==='roundrobin'?roundCount(t.players.length,t.roundRobinFormat):isKnockoutSystem(t.system)?Math.max(1,Math.ceil(Math.log2(Math.max(2,t.players.length)))):isArenaSystem(t.system)?t.arenaRounds:Math.min(t.plannedRounds,roundCount(Math.max(2,count)));confirm('Начинаем турнир?',`${count} ${isTeamSystem(t.system)?'команд':'учасників'} · ${rounds} турів. Список і правила будуть зафіксовані.`,'start-confirm');return}
