  if(a==='remove-player'){const p=t.players.find(p=>p.id===d.id);confirm('Убрать участника?',`Удалить ${esc(p.name)} из списка? Снимок состава останется в истории.`,'remove-player-confirm','data-id="'+esc(d.id)+'"');return}
  if(a==='remove-player-confirm'){if(t.status!=='draft')throw new Error('Склад зафіксовано.');change('Видалений учасник',t=>{t.players=t.players.filter(p=>p.id!==d.id);if(t.system==='roundrobin'&&t.players.length>=2)t.plannedRounds=roundCount(t.players.length,t.roundRobinFormat)});modal.close();return}
